import { useEffect, useMemo, useState } from 'react'
import { api } from '../api'

export type Category = 'crypto' | 'tradfi' | 'commodities' | 'onchain'
export type CatItem = {
  sym: string; base: string; name?: string; sub: string; chain?: string; icon?: string; contract?: string
  price: number; chg: number; high?: number; low?: number; vol: number; mcap?: number; tradable: boolean; spot: boolean
  source?: string; quote?: string; asOf?: string
}

/** Market list for a category from skyd's catalog (Binance data), polled every 10 s. */
export function useCatalog(cat: Category, enabled = true) {
  const [items, setItems] = useState<CatItem[]>([])
  const [state, setState] = useState<'loading' | 'live' | 'offline'>('loading')
  useEffect(() => {
    if (!enabled) return
    let alive = true
    setState('loading')
    setItems([])
    const load = () => api<{ items: CatItem[] }>(`/markets?cat=${cat}`)
      .then(d => { if (alive) { setItems(d.items); setState('live') } })
      .catch(() => { if (alive) setState(s => (s === 'live' ? 'live' : 'offline')) })
    load()
    const id = setInterval(load, 10_000)
    return () => { alive = false; clearInterval(id) }
  }, [cat, enabled])
  return { items, state }
}

export function useAllCatalog(enabled: boolean) {
  const crypto = useCatalog('crypto', enabled)
  const stocks = useCatalog('tradfi', enabled)
  const commodities = useCatalog('commodities', enabled)
  const onchain = useCatalog('onchain', enabled)
  const items = useMemo(() => {
    const bySymbol = new Map<string, CatItem>()
    for (const list of [stocks.items, crypto.items, commodities.items, onchain.items]) {
      for (const item of list) if (!bySymbol.has(item.sym)) bySymbol.set(item.sym, item)
    }
    return [...bySymbol.values()]
  }, [stocks.items, crypto.items, commodities.items, onchain.items])
  const states = [crypto.state, stocks.state, commodities.state, onchain.state]
  const state = states.includes('live') ? 'live' : states.includes('loading') ? 'loading' : 'offline'
  return { items, state } as const
}
